func (m *ConnectionManager) InvalidatePool(key string) {
	key = strings.TrimSpace(key)
	if key == "" || key == "default" {
		return
	}

	var sharedDestDB *gorm.DB
	if m.reg != nil {
		sharedDestDB = m.reg.PeekDB(database.RoleDestination)
	}

	m.masterPoolMu.Lock()
	db, hasDB := m.masterDBPool[key]
	delete(m.masterDBPool, key)

	mc, hasMongo := m.masterMongoPool[key]
	delete(m.masterMongoPool, key)
	delete(m.masterMongoDBs, key)
	delete(m.masterEngines, key)
	m.masterPoolMu.Unlock()

	var regDB *gorm.DB
	if m.reg != nil {
		regDB = m.reg.EvictRole("master:" + key)
	}
	if !hasDB || db == nil {
		db = regDB
	}

	if db != nil && db != sharedDestDB {
		m.retireGormPoolGracefully(key, db)
	}
	if hasMongo && mc != nil {
		_ = mc.Disconnect(context.Background())
		if m.logger != nil {
			m.logger.Info("invalidated master mongo connection pool",
				zap.String("key", key))
		}
	}
}

func (m *ConnectionManager) retireGormPoolGracefully(key string, db *gorm.DB) {
	sqlDB, err := db.DB()
	if err != nil || sqlDB == nil {
		return
	}
	sqlDB.SetMaxIdleConns(0)
	if sqlDB.Stats().InUse == 0 {
		_ = sqlDB.Close()
		if m.logger != nil {
			m.logger.Info("invalidated master connection pool",
				zap.String("key", key))
		}
		return
	}

	m.mu.Lock()
	if m.closed {
		m.mu.Unlock()
		_ = sqlDB.Close()
		return
	}
	m.wg.Add(1)
	m.mu.Unlock()
	go func() {
		defer m.wg.Done()
		ticker := time.NewTicker(200 * time.Millisecond)
		defer ticker.Stop()
		timer := time.NewTimer(15 * time.Second)
		defer timer.Stop()
		for sqlDB.Stats().InUse > 0 {
			select {
			case <-m.stopCh:
				_ = sqlDB.Close()
				return
			case <-timer.C:
				_ = sqlDB.Close()
				return
			case <-ticker.C:
			}
		}
		_ = sqlDB.Close()
		if m.logger != nil {
			m.logger.Info("invalidated master connection pool after draining in-flight queries",
				zap.String("key", key))
		}
	}()
}

func (m *ConnectionManager) Close() {
	m.mu.Lock()
	m.closed = true
	if m.stopCh != nil {
		m.stopOnce.Do(func() { close(m.stopCh) })
	}
	m.mu.Unlock()
	m.wg.Wait()

	var sharedDestDB *gorm.DB
	if m.reg != nil {
		sharedDestDB = m.reg.PeekDB(database.RoleDestination)
	}

	m.masterPoolMu.Lock()
	pools := make(map[string]*gorm.DB, len(m.masterDBPool))

